using namespace std;
using i64=long long;
static i64 nowms(){return chrono::duration_cast<chrono::milliseconds>(chrono::steady_clock::now().time_since_epoch()).count();}
struct Config{string listen,root;uint64_t maxc=0,hbytes=0,htime=0,idle=0,wtime=0,maxreq=0,depth=0;};
static string trim(string s){size_t a=0,b=s.size();while(a<b&&(s[a]==' '||s[a]=='\t'||s[a]=='\r'))a++;while(b>a&&(s[b-1]==' '||s[b-1]=='\t'||s[b-1]=='\r'))b--;return s.substr(a,b-a);}
static bool number(const string&s,uint64_t&x,bool positive=true){if(s.empty())return false;x=0;for(unsigned char c:s){if(c<'0'||c>'9'||x>(UINT64_MAX-(c-'0'))/10)return false;x=x*10+c-'0';}return !positive||x>0;}
static bool config(const char*file,Config&c,sockaddr_in&addr,int&rootfd){ifstream f(file);if(!f)return false;unordered_map<string,string> m;string line;while(getline(f,line)){line=trim(line);if(line.empty()||line[0]=='#')continue;auto p=line.find('=');if(p==string::npos)return false;string k=trim(line.substr(0,p)),v=trim(line.substr(p+1));if(k.empty()||v.empty()||m.count(k)||line.find('\0')!=string::npos)return false;m[k]=v;}if(f.bad()||m.size()!=9)return false;const char*keys[]={"listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth"};for(auto k:keys)if(!m.count(k))return false;c.listen=m["listen"];c.root=m["root"];if(c.root.empty()||c.root[0]!='/')return false;if(!number(m["max_connections"],c.maxc)||!number(m["header_bytes"],c.hbytes)||!number(m["header_timeout_ms"],c.htime)||!number(m["idle_timeout_ms"],c.idle)||!number(m["write_timeout_ms"],c.wtime)||!number(m["max_requests"],c.maxreq)||!number(m["pipeline_depth"],c.depth))return false;if(c.htime>LLONG_MAX/2||c.idle>LLONG_MAX/2||c.wtime>LLONG_MAX/2)return false;auto pos=c.listen.rfind(':');if(pos==string::npos)return false;uint64_t port;if(!number(c.listen.substr(pos+1),port,false)||port>65535)return false;memset(&addr,0,sizeof(addr));addr.sin_family=AF_INET;addr.sin_port=htons(port);if(inet_pton(AF_INET,c.listen.substr(0,pos).c_str(),&addr.sin_addr)!=1)return false;rootfd=open(c.root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);return rootfd>=0;}
static bool tokenchar(unsigned char c){if((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9'))return true;switch(c){case '!':case '#':case '$':case '%':case '&':case '\'':case '*':case '+':case '-':case '.':case '^':case '_':case '`':case '|':case '~':return true;default:return false;}}
static bool ieq(string_view a,string_view b){if(a.size()!=b.size())return false;for(size_t i=0;i<a.size();i++){unsigned char c=a[i],d=b[i];if(c>='A'&&c<='Z')c+=32;if(d>='A'&&d<='Z')d+=32;if(c!=d)return false;}return true;}
static string_view strip(string_view s){while(!s.empty()&&(s.front()==' '||s.front()=='\t'))s.remove_prefix(1);while(!s.empty()&&(s.back()==' '||s.back()=='\t'))s.remove_suffix(1);return s;}
static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<128)continue;unsigned n;uint32_t v,min;if(c>=0xc2&&c<=0xdf){n=1;v=c&31;min=0x80;}else if(c>=0xe0&&c<=0xef){n=2;v=c&15;min=0x800;}else if(c>=0xf0&&c<=0xf4){n=3;v=c&7;min=0x10000;}else return false;if(i+n>s.size())return false;for(unsigned j=0;j<n;j++){unsigned char t=s[i++];if((t&0xc0)!=0x80)return false;v=(v<<6)|(t&63);}if(v<min||v>0x10ffff||(v>=0xd800&&v<=0xdfff))return false;}return true;}
static int hex(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
struct Req{bool head=false,close=false;string path;};
static int parse(string_view h,Req&r){size_t e=h.find("\r\n");if(e==string_view::npos)return 400;string_view l=h.substr(0,e);size_t a=l.find(' '),b=a==string_view::npos?a:l.find(' ',a+1);if(a==string_view::npos||b==string_view::npos||a==0||b==a+1||l.find(' ',b+1)!=string_view::npos)return 400;auto meth=l.substr(0,a),target=l.substr(a+1,b-a-1),ver=l.substr(b+1);for(unsigned char c:meth)if(!tokenchar(c))return 400;if(ver!="HTTP/1.1"&&ver!="HTTP/1.0")return 400;r.head=meth=="HEAD";r.close=ver=="HTTP/1.0";if(target.empty()||target[0]!='/'||target.find('#')!=string_view::npos)return 400;for(unsigned char c:target)if(c<=32||c==127||c=='\\')return 400;auto q=target.find('?');auto path=target.substr(0,q);r.path.reserve(path.size());for(size_t i=0;i<path.size();i++){unsigned char c=path[i];if(c=='%'){if(i+2>=path.size())return 400;int x=hex(path[i+1]),y=hex(path[i+2]);if(x<0||y<0)return 400;c=(x<<4)|y;i+=2;}if(c==0||c=='\\')return 400;r.path.push_back((char)c);}if(!utf8(r.path))return 400;bool cl=false,connclose=false;size_t p=e+2;while(p<h.size()){size_t n=h.find("\r\n",p);if(n==string_view::npos)return 400;if(n==p){p=n+2;break;}auto line=h.substr(p,n-p);if(line[0]==' '||line[0]=='\t')return 400;auto col=line.find(':');if(col==string_view::npos||col==0)return 400;for(unsigned char c:line.substr(0,col))if(!tokenchar(c))return 400;auto name=line.substr(0,col),val=line.substr(col+1);for(unsigned char c:val)if(c==0||c=='\r'||c=='\n')return 400;val=strip(val);if(ieq(name,"transfer-encoding"))return 400;if(ieq(name,"content-length")){if(cl||val.empty())return 400;cl=true;for(char c:val)if(c!='0')return 400;}if(ieq(name,"connection")){while(true){auto t=val.find(',');auto v=strip(val.substr(0,t));if(ieq(v,"close"))connclose=true;if(t==string_view::npos)break;val.remove_prefix(t+1);}}p=n+2;}if(p!=h.size())return 400;r.close|=connclose;if(meth!="GET"&&meth!="HEAD")return 405;return 200;}
static int fileopen(int root,const string&path,int&out,uint64_t&size){vector<string> parts;size_t p=1;bool trailing=path.back()=='/';while(p<=path.size()){size_t n=path.find('/',p);if(n==string::npos)n=path.size();string s=path.substr(p,n-p);if(s=="..")return 403;if(s=="."&&n==path.size())trailing=true;if(!s.empty()&&s!=".")parts.push_back(s);if(n==path.size())break;p=n+1;}if(parts.empty())return 403;int dir=dup(root);if(dir<0)return 404;for(size_t i=0;i<parts.size();i++){bool last=i+1==parts.size();int flags=O_RDONLY|O_CLOEXEC|O_NOFOLLOW|O_NONBLOCK;if(!last)flags|=O_DIRECTORY;int fd=openat(dir,parts[i].c_str(),flags);if(fd<0){int err=errno;struct stat st;bool symlink=fstatat(dir,parts[i].c_str(),&st,AT_SYMLINK_NOFOLLOW)==0&&S_ISLNK(st.st_mode);close(dir);if(symlink||err==ELOOP||err==EACCES||err==EPERM||err==ENOTDIR)return 403;return 404;}close(dir);dir=fd;if(last){struct stat st;if(fstat(fd,&st)<0||!S_ISREG(st.st_mode)||trailing){close(fd);return 403;}out=fd;size=st.st_size;return 200;}}close(dir);return 404;}
struct Conn{int fd=-1,file=-1;string in,out;size_t sent=0;off_t off=0;uint64_t left=0,requests=0;bool writing=false,closeafter=false,again=false;i64 idle=0,first=0,progress=0;};
static const char*reason(int s){switch(s){case 200:return "OK";case 400:return "Bad Request";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 408:return "Request Timeout";case 431:return "Request Header Fields Too Large";default:return "Error";}}
struct Server{Config cfg;int root,ep,listener;unordered_map<int,Conn> cs;
 void drop(int fd){auto it=cs.find(fd);if(it==cs.end())return;if(it->second.file>=0)close(it->second.file);epoll_ctl(ep,EPOLL_CTL_DEL,fd,nullptr);close(fd);cs.erase(it);}
 void arm(Conn&c){epoll_event e{};e.events=EPOLLRDHUP|(c.writing?EPOLLOUT:EPOLLIN)|(c.again?EPOLLOUT:0);e.data.fd=c.fd;epoll_ctl(ep,EPOLL_CTL_MOD,c.fd,&e);}
 void response(Conn&c,int status,Req&r,i64 now){uint64_t len=0;int f=-1;if(status==200)status=fileopen(root,r.path,f,len);if(status!=200){if(f>=0)close(f);f=-1;len=0;}c.requests++;c.closeafter=r.close||c.requests>=cfg.maxreq||status==400||status==431||status==408;c.out="HTTP/1.1 "+to_string(status)+" "+reason(status)+"\r\nContent-Length: "+to_string(len)+"\r\nConnection: "+(c.closeafter?string("close"):string("keep-alive"))+"\r\n";if(status==200)c.out+="Content-Type: application/octet-stream\r\n";if(status==405)c.out+="Allow: GET, HEAD\r\n";c.out+="\r\n";c.sent=0;c.off=0;c.left=r.head?0:len;c.file=f;if(c.left==0&&c.file>=0){close(c.file);c.file=-1;}c.writing=true;c.progress=now;}
 bool pump(Conn&c,i64 now){c.again=false;size_t work=0;int rounds=0;if(!c.writing&&!c.in.empty()&&c.in.find("\r\n\r\n")==string::npos&&now-c.first>=(i64)cfg.htime){Req r;r.close=true;response(c,408,r,now);c.in.clear();}while(rounds++<32&&work<1048576){if(c.writing){while(c.sent<c.out.size()){ssize_t n=send(c.fd,c.out.data()+c.sent,c.out.size()-c.sent,MSG_NOSIGNAL|(c.left?MSG_MORE:0));if(n>0){c.sent+=n;c.progress=now;work+=n;}else if(n<0&&errno==EINTR)continue;else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return true;else return false;}while(c.left){size_t chunk=(size_t)min<uint64_t>(c.left,1048576-work);if(!chunk){c.again=true;return true;}ssize_t n=sendfile(c.fd,c.file,&c.off,chunk);if(n>0){c.left-=n;c.progress=now;work+=n;}else if(n<0&&errno==EINTR)continue;else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return true;else return false;}if(c.file>=0){close(c.file);c.file=-1;}c.writing=false;c.out.clear();if(c.closeafter)return false;c.idle=now;}
 size_t end=c.in.find("\r\n\r\n");if(end!=string::npos){Req r;int s=parse(c.in,r);c.in.clear();c.first=0;response(c,s,r,now);continue;}
 bool bad=false;for(size_t i=0;i<c.in.size();i++){unsigned char x=c.in[i];if(x==0||(x=='\n'&&(i==0||c.in[i-1]!='\r'))||(x=='\r'&&i+1<c.in.size()&&c.in[i+1]!='\n')){bad=true;break;}}if(bad){Req r;r.close=true;response(c,400,r,now);c.in.clear();continue;}if(c.in.size()>=cfg.hbytes){Req r;r.close=true;response(c,431,r,now);c.in.clear();continue;}
 size_t cap=(size_t)min<uint64_t>(8192,cfg.hbytes-c.in.size());char buf[8192];ssize_t n=recv(c.fd,buf,cap,MSG_PEEK);if(n>0){size_t take=n;string_view peek(buf,n);auto pos=peek.find("\r\n\r\n");if(pos!=string_view::npos)take=pos+4;size_t tail=min<size_t>(3,c.in.size());string edge=c.in.substr(c.in.size()-tail);edge.append(buf,min<size_t>(3,n));auto cross=edge.find("\r\n\r\n");if(cross!=string::npos&&cross<tail)take=min(take,cross+4-tail);ssize_t got=recv(c.fd,buf,take,0);if(got>0){if(c.in.empty())c.first=now;c.in.append(buf,got);c.idle=now;work+=got;continue;}if(got<0&&errno==EINTR)continue;if(got<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return true;return false;}if(n==0)return false;if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK)return true;return false;}c.again=true;return true;}
 int run(){ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return 1;epoll_event e{};e.events=EPOLLIN;e.data.fd=listener;if(epoll_ctl(ep,EPOLL_CTL_ADD,listener,&e)<0)return 1;array<epoll_event,1024> ev;i64 sweep=nowms();while(true){i64 before=nowms();int wait=(int)max<i64>(0,10-(before-sweep));int n=epoll_wait(ep,ev.data(),ev.size(),wait);i64 now=nowms();if(n<0){if(errno==EINTR)continue;return 1;}for(int i=0;i<n;i++){int fd=ev[i].data.fd;if(fd==listener){for(int z=0;z<128;z++){int x=accept4(listener,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(x<0){if(errno==EINTR){z--;continue;}break;}if(cs.size()>=cfg.maxc){close(x);continue;}int one=1;setsockopt(x,IPPROTO_TCP,TCP_NODELAY,&one,sizeof(one));Conn c;c.fd=x;c.idle=now;cs.emplace(x,move(c));epoll_event a{};a.events=EPOLLIN|EPOLLRDHUP;a.data.fd=x;if(epoll_ctl(ep,EPOLL_CTL_ADD,x,&a)<0)drop(x);}continue;}auto it=cs.find(fd);if(it==cs.end())continue;if(ev[i].events&EPOLLERR){drop(fd);continue;}if(!pump(it->second,now)){drop(fd);continue;}arm(it->second);}now=nowms();if(now-sweep>=10){sweep=now;vector<int> dead;for(auto&[fd,c]:cs){if(c.writing){if(now-c.progress>=(i64)cfg.wtime)dead.push_back(fd);}else if(!c.in.empty()){if(now-c.first>=(i64)cfg.htime){Req r;r.close=true;response(c,408,r,now);c.in.clear();if(!pump(c,now))dead.push_back(fd);else arm(c);}}else if(now-c.idle>=(i64)cfg.idle)dead.push_back(fd);}for(int fd:dead)drop(fd);}}}
};
int main(int argc,char**argv){signal(SIGPIPE,SIG_IGN);if(argc!=3||string(argv[1])!="--config")return 1;Server s{};sockaddr_in addr{};if(!config(argv[2],s.cfg,addr,s.root))return 1;s.listener=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(s.listener<0)return 1;int one=1;setsockopt(s.listener,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));if(bind(s.listener,(sockaddr*)&addr,sizeof(addr))<0||listen(s.listener,8192)<0)return 1;return s.run();}
